def place(row, k):                       # k rooks are still to be placed
    if k == 0:
        return 1
    if row == n:
        return 0                          # the board is over but rooks are missing
    total = place(row + 1, k)             # no rook in this row
    for col in range(n):
        if board[row][col] == "." and not cols[col]:
            cols[col] = True
            total += place(row + 1, k - 1)
            cols[col] = False
    return total

