def place(board, n, row, k, cols):
    if k == 0:
        return 1
    if n - row < k:
        return 0
    total = place(board, n, row + 1, k, cols)
    for col in range(n):
        if board[row][col] == "." and not cols[col]:
            cols[col] = True
            total += place(board, n, row + 1, k - 1, cols)
            cols[col] = False
    return total

