import java.util.*;

public class Main {
    static long place(String[] board, int n, int row, int k, boolean[] cols) {
        if (k == 0) return 1;
        if (n - row < k) return 0;
        long total = place(board, n, row + 1, k, cols);
        for (int col = 0; col < n; col++) {
            if (board[row].charAt(col) == '.' && !cols[col]) {
                cols[col] = true;
                total += place(board, n, row + 1, k - 1, cols);
                cols[col] = false;
            }
        }
        return total;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();
        String[] board = new String[(int) n];
        for (int i = 0; i < board.length; i++) {
            board[i] = sc.next();
        }

        System.out.println(place(board, (int) n, 0, (int) k, new boolean[(int) n]));
    }
}
